WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.OwnerUserId, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn FROM Posts AS p WHERE p.PostTypeId = 1), RecentActivity AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(DISTINCT p.Id) AS QuestionCount, COALESCE(SUM(v.BountyAmount), 0) AS TotalBounty FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId AND p.PostTypeId = 1 LEFT JOIN Votes AS v ON p.Id = v.PostId AND v.VoteTypeId IN (8, 9) WHERE u.Reputation > 1000 GROUP BY u.Id, u.DisplayName), ClosedReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON ph.Comment = CAST(cr.Id AS Nullable(String)) WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId), PostCounts AS (SELECT PostId, COUNT(*) AS CommentCount FROM Comments GROUP BY PostId) SELECT ra.DisplayName, ra.QuestionCount, ra.TotalBounty, r.PostId, r.Title, r.CreationDate, COALESCE(pc.CommentCount, 0) AS CommentCount, COALESCE(cr.CloseReasons, 'Not Closed') AS CloseReasons FROM RecentActivity AS ra JOIN RankedPosts AS r ON ra.UserId = r.OwnerUserId AND r.rn = 1 LEFT JOIN PostCounts AS pc ON r.PostId = pc.PostId LEFT JOIN ClosedReasons AS cr ON r.PostId = cr.PostId WHERE ra.QuestionCount > 5 ORDER BY ra.TotalBounty DESC NULLS FIRST, ra.QuestionCount DESC NULLS FIRST